namespace MapgenStudio;

/// <summary>
/// Every text of the interface, in Russian and English (R2), from one table. <see cref="T"/> returns the current
/// language's text; a missing key shows itself as <c>[key]</c> so nothing is silently blank.
/// </summary>
public static class Loc
{
    public static string Language { get; set; } = "ru";

    public static string T(string key) =>
        (Language == "en" ? En : Ru).TryGetValue(key, out var s) ? s
        : Ru.TryGetValue(key, out var r) ? r : $"[{key}]";

    public static string F(string key, params object[] args) => string.Format(T(key), args);

    /// <summary>A word in a given language, whatever the program's is (brief 23: a preset's name is refused in both).</summary>
    public static string In(string lang, string key) =>
        (lang == "en" ? En : Ru).TryGetValue(key, out var s) ? s : T(key);

    /* the PO, 04.11: «откуда например Переделка основы в новой карте? ... проверяй всё такое» - a map from scratch has
       no base: a text that names one has its variant for such a map, its key with «.s» */
    public static string Ks(string key, bool scratch) => scratch && Has(key + ".s") ? key + ".s" : key;
    public static string Ts(string key, bool scratch) => T(Ks(key, scratch));
    public static string Fs(string key, bool scratch, params object[] args) => string.Format(Ts(key, scratch), args);

    public static bool Has(string key) => Ru.ContainsKey(key);

    public static bool HasIn(string lang, string key) => (lang == "en" ? En : Ru).ContainsKey(key);

    /// <summary>Every text of one language's table (3.58's self-test reads the Studio's own words).</summary>
    internal static IEnumerable<(string key, string text)> Table(string lang) =>
        (lang == "en" ? En : Ru).Select(kv => (kv.Key, kv.Value));

    /// <summary>
    /// The gate's key in the string table (S-1, brief 4): the word before its colon, and for the two «pickups»
    /// checks which one it is.
    /// </summary>
    /* brief 14 F2: the checks asked again after the ruin are «after destruction: <check>: ...» - the check's own words
       with «после разрушений» (the self-test on the PO's library found [gate.after destruction] on the map page) */
    private const string AfterRuin = "after destruction:";

    internal static string WithoutAfterRuin(string what) =>
        what.TrimStart().StartsWith(AfterRuin, StringComparison.OrdinalIgnoreCase) ? what.TrimStart()[AfterRuin.Length..].TrimStart() : what;

    public static string GateKey(string what)
    {
        what = WithoutAfterRuin(what);
        var colon = what.IndexOf(':');
        var word = (colon > 0 ? what[..colon] : what).Trim().ToLowerInvariant();
        if (word == "pickups")
            word = what.Contains("chaingun", StringComparison.OrdinalIgnoreCase) ? "pickups.chaingun" : "pickups.spawn";
        return "gate." + word;
    }

    /// <summary>A check in plain words; one the table does not know keeps its own line (never silence).</summary>
    public static string Gate(string what) =>
        (Has(GateKey(what)) ? T(GateKey(what)) : what)
        + (WithoutAfterRuin(what) != what && Has(GateKey(what)) ? T("gate.after_ruin") : "");

