        ["gen.sub.s"] = "Задайте, какой должна быть карта, — генератор построит её с нуля",
        ["gen.card.map.desc.s"] = "Сколько времени дать генератору, номер варианта и имя",
        ["gen.speed.desc.s"] = "Сколько времени может идти генерация: 15, 30, 60 или 120 минут. Правее — дольше, и отделка правками успеет больше; левее — быстрее. Генерация остановится и раньше, если отделка набрала заказанное или её план исчерпан",
        ["gen.seed.desc.s"] = "Одинаковые параметры и номер дают одну и ту же карту; другой номер — другую.",
        ["run.diff.head.s"] = "Отделка: отличие от каркаса",
        ["run.likeness.s"] = "Отделка уже изменила карту каркаса на {0}%, заказано {1}%",
        ["run.likeness.tip.s"] = "Насколько правки отделки уже изменили карту, собранную из каркаса, против заказанного в «Отделка правками». Отличие считается по самой этой карте: её объём делится на кубики со стороной 32 единицы, и отличие — доля кубиков, где что-то стало другим: камень стал воздухом или наоборот, сдвинулся пол или стена, поменялась высота или путь игрока.",
        ["run.plan.value.tip.s"] = "Генератор ещё до первой сборки проверяет каждую правку отделки на самой геометрии и прикидывает, сколько кубиков карты каркаса она изменит. Здесь — сумма лучших из них на оставшиеся сборки: больше этого план не даст",
        ["result.ERR_TARGET_UNREACHABLE.delivered.s"] = "Отделка правками изменила карту меньше заказанного — её план исчерпан; карта готова такой, какой её построил каркас.",
        ["stage.start.tip.s"] = "Генератор читает карту, собранную из каркаса",
