        ["run.stages"] = "Ход работы",
        ["gen.warp"] = "Каркас основы",
        ["gen.warp.desc"] = "Генератор сначала меняет саму основу, а уже потом достраивает: растягивает и сжимает её части по-разному. Увеличенная карта растёт и в высоту — пропорционально; перед ступенями и уступами, на которые иначе было бы не подняться, появляются пологие заезды, лифты и батуты подстраиваются.",
        ["gen.warp.tip"] = "Карта разрезается по длине и ширине на несколько частей, и каждая часть растягивается или сжимается по-своему: одна комната становится вдвое длиннее, проход рядом — короче, двор — шире. Линии разреза генератор выбирает сам и не проводит их через двери, лифты, поезда и их пути. Растянутую карту он собирает и проверяет на проходимость один раз, до первой правки; если она не проходит, пробует вариант мягче",
        ["gen.warp.size"] = "Размер карты",
        ["gen.warp.size.tip"] = "Площадь новой карты от площади основы, от 10 до 1000 %. 100 % — размер прежний. Сколько карта может принять, столько и получит: ни одна часть не сжимается так, чтобы проход стал уже игрока, и карта не выходит за пределы, которые держит игра",
        ["gen.warp.size.value"] = "{0} %",
        ["gen.warp.shape"] = "Разные пропорции частей",
        ["gen.warp.shape.tip"] = "0 — вся карта растягивается одинаково. Чем правее, тем сильнее части отличаются друг от друга: при 100 % одни части почти вдвое длиннее среднего, другие короче. Это и меняет сам каркас",
        ["gen.warp.shape.value"] = "{0} %",
        ["gen.warp.shift"] = "Сдвиг частей",
        ["gen.warp.shift.tip"] = "Части карты сдвигаются вбок друг относительно друга: комнаты одной части оказываются смещены против соседней, а проходы между частями изгибаются — получается другое расположение комнат. Полы остаются ровными, стены вертикальными; части с дверями, лифтами и поездами переносятся целиком, без перекоса. 0 — без сдвига",
        ["gen.warp.shift.value"] = "{0} %",
        ["gen.warp.turn"] = "Поворот основы",
        ["gen.warp.turn.tip"] = "Вся основа поворачивается или отражается зеркально: те же места оказываются по другим сторонам. Двери, лифты, прыжковые площадки, взгляд игроков на старте и текстуры поворачиваются вместе с ней. «Случайно» — выбирает зерно генерации",
        ["gen.warp.turn.none"] = "Как в основе",
        ["gen.warp.turn.90"] = "Повернуть на 90°",
        ["gen.warp.turn.180"] = "Повернуть на 180°",
        ["gen.warp.turn.270"] = "Повернуть на 270°",
        ["gen.warp.turn.mirror"] = "Отразить зеркально",
        ["gen.warp.turn.seed"] = "Случайно (по зерну)",
        ["gen.warp.height"] = "Высота потолков",
        ["gen.warp.height.tip"] = "Сверх пропорциональной высоты: всё, что выше самого высокого места, где может стоять игрок, поднимается ещё — залы верхнего уровня становятся выше, небо тоже. 100 % — пропорционально размеру карты",
        ["gen.warp.height.value"] = "{0} %",
        ["run.warp.ok"] = "Каркас основы изменён: площадь {0} % от исходной, части растянуты от {1} до {2} раза; карта собрана и проходима",
        ["run.warp.no"] = "Растянутый вариант (площадь {0} %, части от {1} до {2} раза) не прошёл проверку проходимости — пробую мягче",
        ["run.warp.kept"] = "Каркас основы оставлен прежним: растянутая карта не прошла проверку, генерация идёт на исходной основе",
        ["run.warp.height.cut"] = "Потолки подняты до {0} % из заказанных {1} %: выше не позволяют координаты игры",
        ["run.warp.height.kept"] = "Потолки оставлены пропорциональными: карта с потолками выше не прошла проверку",
        ["gen.grp.rooms"] = "Новые помещения",
        ["gen.grp.rooms.desc"] = "Что генератор достраивает к основе: проходы, пристройки, залы, мосты и лестницы. «По умолчанию» — решает генератор по похожести.",
