        ["scheme.cut.all"] = "все",
        ["scheme.cut.at"] = "до {0}",
        ["scheme.legend"] = "Карта в объёме. Левая кнопка мыши — вращать, правая — сдвигать, колесо — ближе/дальше, двойной щелчок — вид сверху. Синее мигает — правка пробуется; красное — отклонена (гаснет за 10 с); зелёное — принята, потом становится коричневым; бирюзовое с надписью — изменена сама основа карты (стена сдвинута или повёрнута, терраса, блок, помост, перестроено помещение, новый проём и т. п.), пока идут правки; потом гаснет, как зелёное. Полы тем светлее, чем выше; вода синяя, лава оранжевая, слизь зелёная, лифты и двери сиреневые. Оружие — жёлтый треугольник, броня — голубой ромб, аптечки — белый крест, патроны — серые точки, усилители — лиловый круг, места появления — белое кольцо, телепорты — розовое кольцо.",
