        ["run.likeness.tip"] = "Насколько новая карта уже отличается от основы, против того, что просили. Отличие считается по самой основе: её объём делится на кубики со стороной 32 единицы, и отличие — доля кубиков, где что-то стало другим: камень стал воздухом или наоборот, сдвинулся пол или стена, поменялась высота, путь игрока или повторяющийся узор. Пристройка снаружи основы прибавляет отличие только там, где врезается в неё; перестройка самой основы прибавляет его больше всего.",
