        ["run.likeness.tip.s"] = "How far the dressing edits have already changed the map built from the skeleton, against what «Dressing edits» asked. It is counted on that map itself: its volume is cut into cubes 32 units a side, and the difference is the share of the cubes where something changed - rock became air or the other way round, a floor or a wall moved, a height or a player's way changed.",
        ["run.plan.value.tip.s"] = "Before its first build the generator checks every dressing edit on the geometry itself and works out how many cubes of the skeleton's map it would change. This is the sum of the best of them for the builds left: the plan gives no more",
