        ["home.sub"] = "New Quake II maps - from existing ones and from scratch · version {0}",
        ["home.intro1"] = "MAPGEN Studio makes new Quake II maps - out of existing ones or from scratch. From an existing map: you choose a base map - q2dm1, say - and how far the new map should differ from it. From scratch: you set how many players the map is for, how many levels, lifts and how much water it has, which weapons and in which style - and the generator builds it itself. The Studio shows how the work goes, keeps the finished maps in its library, takes their covers and puts a map into the game with one click.",
        ["home.intro2"] = "From an existing map the generator takes the base and remakes it step by step - stretches and shifts its parts, digs new passages, builds on rooms, two-storey halls, bridges, windows and pools, rebuilds walls, floors and stairs. From scratch it first lays out a skeleton - rooms, levels, ways between them and the places of items, by the rules of well-known maps - and builds the map from it. Every edit is built into a real map and checked: can every place be walked to, can every item and spawn be reached, is there no hole to the outside. Edits that fail are thrown away, so what comes out is always a playable map.",
        ["home.act.generate"] = "New map",
        ["home.act.generate.desc"] = "A new map from existing ones or from scratch",
