        ["home.steps.desc"] = "Four steps",
        ["home.step1"] = "On the Generate page tick a base map - one or several - or choose «A new map from scratch» and set its parameters.",
        ["home.step2"] = "Set the generation's time; for a map from an existing one - the likeness to the base and, if you like, the scope of the changes, for a map from scratch - the players, size, ways up, liquids, weapons, mechanics and style.",
        ["home.step3"] = "Press «Start generating» and follow it: for a new map the whole build's percent and the time left, for a map from a ready one the difference from the base; the edits, the plan and the map's scheme update as you watch.",
